 SELECT CASE WHEN OLD.status!='active' OR NEW.status!='reversed' OR NOT EXISTS(SELECT 1 FROM lp_purchase_invoices WHERE id=OLD.invoice_id AND status='draft') OR NEW.original_json!=OLD.original_json OR NEW.allocations_json!=OLD.allocations_json OR NEW.invoice_id!=OLD.invoice_id OR NEW.id!=OLD.id OR NEW.original_line_id!=OLD.original_line_id OR NEW.reason!=OLD.reason OR NEW.stock_unit!=OLD.stock_unit OR NEW.total_quantity_milli!=OLD.total_quantity_milli THEN RAISE(ABORT,'SPLIT_LOCKED') END;
